  "Last 30 games (accuracy)": { es: "Últimas 30 partidas (precisión)", ar: "آخر 30 لعبة (الدقة)", zh: "最近 30 局（正确率）", sw: "Michezo 30 ya mwisho (usahihi)", sv: "Senaste 30 omgångarna (träffsäkerhet)" },
  "Play a game to see your progress here.": { es: "Juega una partida para ver aquí tu progreso.", ar: "العب لعبة لترى تقدمك هنا.", zh: "玩一局即可在这里看到进度。", sw: "Cheza mchezo uone maendeleo yako hapa.", sv: "Spela en omgång för att se dina framsteg här." },
  "⬇ Download my results (CSV)": { es: "⬇ Descargar mis resultados (CSV)", ar: "⬇ نزّل نتائجي (CSV)", zh: "⬇ 下载我的成绩（CSV）", sw: "⬇ Pakua matokeo yangu (CSV)", sv: "⬇ Ladda ner mina resultat (CSV)" },
