  "Greek letters": { es: "Letras griegas", ar: "حروف يونانية", zh: "希腊字母", sw: "Herufi za Kigiriki", sv: "Grekiska bokstäver" },
  "Letters": { es: "Letras", ar: "حروف", zh: "字母", sw: "Herufi", sv: "Bokstäver" },
