  "Different symbols to choose from": { es: "Símbolos distintos entre los que elegir", ar: "رموز مختلفة للاختيار منها", zh: "可选的不同符号", sw: "Alama tofauti za kuchagua", sv: "Olika symboler att välja mellan" },
  "Symbol set": { es: "Conjunto de símbolos", ar: "مجموعة الرموز", zh: "符号集", sw: "Seti ya alama", sv: "Symboluppsättning" },
  "Seconds before they hide": { es: "Segundos antes de ocultarse", ar: "ثوانٍ قبل الإخفاء", zh: "隐藏前的秒数", sw: "Sekunde kabla ya kujificha", sv: "Sekunder innan de döljs" },
  "Without time they hide when you tap 1": { es: "Sin tiempo se ocultan cuando tocas el 1", ar: "بلا وقت تختفي عند النقر على 1", zh: "不计时时，点击 1 后它们会隐藏", sw: "Bila muda zinajificha unapogusa 1", sv: "Utan tid döljs de när du trycker på 1" },
  "How many pairs": { es: "Cuántas parejas", ar: "كم زوجًا", zh: "配对数量", sw: "Jozi ngapi", sv: "Hur många par" },
  "Cards show": { es: "Las cartas muestran", ar: "تعرض البطاقات", zh: "卡片显示", sw: "Kadi zinaonyesha", sv: "Korten visar" },
  "Symbols": { es: "Símbolos", ar: "رموز", zh: "符号", sw: "Alama", sv: "Symboler" },
