  "Numbers and symbols": { es: "Números y símbolos", ar: "أرقام ورموز", zh: "数字和符号", sw: "Namba na alama", sv: "Siffror och symboler" },
  "Peek at all cards first (seconds)": { es: "Ver antes todas las cartas (segundos)", ar: "ألقِ نظرة على كل البطاقات أولًا (ثوانٍ)", zh: "先偷看所有卡片（秒）", sw: "Chungulia kadi zote kwanza (sekunde)", sv: "Kika på alla kort först (sekunder)" },
  "N (how many steps back)": { es: "N (cuántos pasos atrás)", ar: "N (كم خطوة للخلف)", zh: "N（往回几步）", sw: "N (hatua ngapi nyuma)", sv: "N (hur många steg tillbaka)" },
  "Track": { es: "Seguir", ar: "التتبع", zh: "追踪", sw: "Fuatilia", sv: "Följ" },
  "Card only": { es: "Solo la carta", ar: "البطاقة فقط", zh: "仅卡片", sw: "Kadi tu", sv: "Bara kort" },
  "Card and position (dual)": { es: "Carta y posición (doble)", ar: "البطاقة والموضع (مزدوج)", zh: "卡片和位置（双重）", sw: "Kadi na mahali (mara mbili)", sv: "Kort och position (dubbel)" },
  "Numbers are": { es: "Los números se", ar: "الأرقام", zh: "数字", sw: "Namba", sv: "Siffrorna" },
  "Shown in the square": { es: "Muestran en el cuadrado", ar: "تُعرض في المربع", zh: "显示在方块中", sw: "Zinaonyeshwa ndani ya mraba", sv: "Visas i rutan" },
  "Read aloud (classic dual n-back)": { es: "Leen en voz alta (dual n-back clásico)", ar: "تُقرأ بصوت عالٍ (dual n-back الكلاسيكي)", zh: "朗读（经典双重 n-back）", sw: "Zinasomwa kwa sauti (dual n-back ya kawaida)", sv: "Läses upp (klassisk dual n-back)" },
  "Shown and read aloud": { es: "Muestran y leen en voz alta", ar: "تُعرض وتُقرأ بصوت عالٍ", zh: "显示并朗读", sw: "Zinaonyeshwa na kusomwa kwa sauti", sv: "Visas och läses upp" },
  "Read aloud keeps the number and the square on separate senses": { es: "Leer en voz alta mantiene el número y el cuadrado en sentidos distintos", ar: "القراءة بصوت عالٍ تُبقي الرقم والمربع على حاستين منفصلتين", zh: "朗读让数字和方块分别通过不同感官接收", sw: "Kusoma kwa sauti kunaweka namba na mraba kwenye hisi tofauti", sv: "Uppläsning håller siffran och rutan på olika sinnen" },
  "Rounds": { es: "Rondas", ar: "الجولات", zh: "轮数", sw: "Raundi", sv: "Omgångar" },
  "Seconds per round": { es: "Segundos por ronda", ar: "ثوانٍ لكل جولة", zh: "每轮秒数", sw: "Sekunde kwa kila raundi", sv: "Sekunder per omgång" },
  "Without time each round waits for your answer": { es: "Sin tiempo, cada ronda espera tu respuesta", ar: "بلا وقت تنتظر كل جولة إجابتك", zh: "不计时时，每轮都会等你作答", sw: "Bila muda kila raundi inasubiri jibu lako", sv: "Utan tid väntar varje omgång på ditt svar" },
